import pyomo.environ as pyo

DATA = {
    "products": ["chocolate", "vanilla"],
    "profit": {"chocolate": 200, "vanilla": 300},
    "min_gallons": {"chocolate": 5, "vanilla": 5},
    "max_gallons": {"chocolate": 10, "vanilla": 8},
    "hours_per_gallon": {"chocolate": 1, "vanilla": 2},
    "hours_available": 30,
    "workers_per_gallon": {"chocolate": 1, "vanilla": 2},
    "min_workers": 6,
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.PRODUCTS = pyo.Set(initialize=d["products"])

    def gallon_bounds(m, p):
        return (d["min_gallons"][p], d["max_gallons"][p])

    model.production = pyo.Var(
        model.PRODUCTS,
        domain=pyo.NonNegativeReals,
        bounds=gallon_bounds,
    )

    def profit_rule(m):
        return sum(d["profit"][p] * m.production[p] for p in m.PRODUCTS)

    model.obj = pyo.Objective(expr=profit_rule, sense=pyo.maximize)

    def hours_rule(m):
        return sum(
            d["hours_per_gallon"][p] * m.production[p] for p in m.PRODUCTS
        ) <= d["hours_available"]

    model.hours_limit = pyo.Constraint(rule=hours_rule)

    def workers_rule(m):
        return sum(
            d["workers_per_gallon"][p] * m.production[p] for p in m.PRODUCTS
        ) >= d["min_workers"]

    model.workers_min = pyo.Constraint(rule=workers_rule)

    return model


