import pyomo.environ as pyo

DATA = {
    "products": ["chocolate", "vanilla"],
    "profit": {"chocolate": 200, "vanilla": 300},
    "min_gallons": {"chocolate": 5, "vanilla": 5},
    "max_gallons": {"chocolate": 10, "vanilla": 8},
    "labor_per_gallon": {"chocolate": 1, "vanilla": 2},
    "labor_available": 30,
    "workers_per_gallon": {"chocolate": 1, "vanilla": 2},
    "min_workers": 6,
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.P = pyo.Set(initialize=d["products"])

    def bounds_rule(m, p):
        return (d["min_gallons"][p], d["max_gallons"][p])

    model.x = pyo.Var(model.P, domain=pyo.NonNegativeReals, bounds=bounds_rule)

    def obj_rule(m):
        return sum(d["profit"][p] * m.x[p] for p in m.P)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    def labor_rule(m):
        return sum(d["labor_per_gallon"][p] * m.x[p] for p in m.P) <= d["labor_available"]

    model.labor = pyo.Constraint(rule=labor_rule)

    def workers_rule(m):
        return sum(d["workers_per_gallon"][p] * m.x[p] for p in m.P) >= d["min_workers"]

    model.workers = pyo.Constraint(rule=workers_rule)

    return model


